rng=np.random.default_rng(112)
n=45000
X=np.zeros((n,20)); X[:,0]=rng.uniform(-4.2,4,n); X[:,1:10]=rng.integers(0,2,(n,9)); X[:,10:]=rng.uniform(0,10,(n,10))
y=predict(X).reshape(-1)
U=[]
for j in range(20):
    a=X[:,j]
    if j==0 or j>=10:
        low,high=(-4.2,4) if j==0 else (0,10)
        a=(a-low)/(high-low)*2-1
        f=[a, (3*a*a-1)/2, (5*a**3-3*a)/2,(35*a**4-30*a*a+3)/8]
        f=np.array(f).T*np.sqrt(np.array([3,5,7,9]))
    else:
        f=(a[:,None]-.5)*2
    U.append(f)
for deg in [1,2,3,4]:
    F=[np.ones(n)]; names=[["int"]]
    for j in range(20):
        for k in range(U[j].shape[1]):
            F.append(U[j][:,k]); names.append([j,k])
    for j in range(20):
        for k in range(j+1,20):
            for a in range(min(deg,U[j].shape[1])):
                for b in range(min(deg,U[k].shape[1])):
                    if a+b>deg: continue
                    F.append(U[j][:,a]*U[k][:,b]); names.append([j,k,a,b])
    A=np.array(F).T
    p=A.shape[1]; nt=35000
    aa=A[:nt]
    b=np.linalg.solve(aa.T@aa+np.eye(p)*50,aa.T@y[:nt])
    err=y[nt:]-A[nt:]@b
    print("degree",deg,"p",p,"rmse",round(float(np.sqrt(np.mean(err**2))),6),"r2",round(float(1-np.var(err)/np.var(y[nt:])),6))
    if deg==4:
        print("strongest interaction components", [(a,round(float(v),5)) for a,v in sorted(zip(names,b),key=lambda x:-abs(x[1])) if len(a)==4][:80])

